parameters.jsCode:
// Parse Slack interactivity payload, verify token + allow-list, normalise the requested action
const cfg = $('Set Workflow Config').first().json;
let p;
try { p = JSON.parse($input.first().json.body.payload); } catch (e) { return []; }
if (p.type !== 'block_actions' || !p.actions?.length) return [];
if (cfg.slack_verification_token && p.token !== cfg.slack_verification_token) return []; // silently drop spoofed calls
const a = p.actions[0];
if (!a.value) return []; // link buttons (Open Ads Manager)
let v = {};
try { v = JSON.parse(a.value); } catch (e) { return []; }
const allowed = String(cfg.slack_allowed_user_ids || '').split(',').map(s => s.trim()).filter(Boolean);
const user = p.user?.id;
const action = allowed.length && !allowed.includes(user) ? 'deny' : v.a;
return [{ json: {
  action, requested: v.a, ad_id: v.ad || null, adset_id: v.adset || null, entity_name: v.n || '', budget_pct: Number(v.p) || 0,
  fingerprints: v.fps || (v.fp ? [v.fp] : []), account_id: v.acc, client: v.c,
  user_id: user, user_name: p.user?.username || p.user?.name || user,
  response_url: p.response_url, channel_id: p.channel?.id, message_ts: p.message?.ts || p.container?.message_ts,
  graph_version: cfg.graph_version, snooze_days: Number(cfg.snooze_days) || 3, max_budget_change_pct: Number(cfg.max_budget_change_pct) || 30
}}];

// One item per ad account with IST date windows for every API call
const c = $('Set Workflow Config').first().json;
let accs;
try { accs = JSON.parse(c.ad_accounts); } catch (e) { throw new Error('Config → ad_accounts must be a valid JSON array'); }
const now = DateTime.now().setZone('Asia/Kolkata');
const y = now.minus({ days: 1 });
const d = x => x.toISODate();
const tr = (from) => JSON.stringify({ since: d(from), until: d(y) });
const { ad_accounts, ...rest } = c;
return accs.map(a => ({ json: {
  ...rest,
  account_id: String(a.id).startsWith('act_') ? String(a.id) : 'act_' + a.id,
  client_name: a.client || a.id, goal: a.goal || 'conversions',
  target_cpa: a.target_cpa || null, slack_channel: a.slack_channel || c.default_slack_channel,
  until: d(y),
  range_baseline: tr(y.minus({ days: Number(c.baseline_days) || 28 })),
  range_ads_daily: tr(y.minus({ days: 13 })),
  range_7d: tr(y.minus({ days: 6 }))
}}));

// Snooze / resolve → alert-log updates only
const a = $input.first().json;
const tz = 'Asia/Kolkata';
const now = DateTime.now().setZone(tz);
const isSnooze = a.action === 'snooze';
const until = now.plus({ days: a.snooze_days }).toISODate();
return [{ json: { ...a, ok: true,
  text: isSnooze ? `😴 <@${a.user_id}> snoozed ${a.fingerprints.length} alert(s) for ${a.client} until ${until}.` : `✅ <@${a.user_id}> marked ${a.fingerprints.length} alert(s) for ${a.client} as handled.`,
  alert_updates: a.fingerprints.map(fp => ({ fingerprint: fp, status: isSnooze ? 'snoozed' : 'resolved', snoozed_until: isSnooze ? until : '', last_action: a.action, last_action_by: a.user_name, updated_at: now.toISO() })),
  log: { action: a.action, entity_id: a.fingerprints.join(' ; ').slice(0, 300), before: '', after: isSnooze ? `until ${until}` : 'resolved' } } }];

// Agency-wide run summary for the ops channel
const cfg = $('Set Workflow Config').first().json;
if (!cfg.ops_slack_channel) return [];
const rows = $input.all().map(i => i.json).filter(r => r.client);
const cur = cfg.currency_symbol;
const icon = { critical: '🔴', warning: '🟠', info: '🔵', ok: '🟢' };
const order = { critical: 0, warning: 1, info: 2, ok: 3 };
rows.sort((a, b) => order[a.severity] - order[b.severity]);
const total = rows.reduce((s, r) => s + (Number(r.spend) || 0), 0);
const lines = rows.map(r => `${icon[r.severity] || '⚪'} *${r.client}* — ${r.active} active${r.critical ? ` (${r.critical} critical)` : ''}${r.fatigued ? ` · ${r.fatigued} fatigued ads` : ''}${r.scale ? ` · ${r.scale} scale opps` : ''}${r.suppressed ? ` · ${r.suppressed} snoozed` : ''}${r.recovered ? ` · ${r.recovered} recovered` : ''}`);
return [{ json: { slack_channel: cfg.ops_slack_channel,
  text: `*📊 Meta Ads daily check — ${rows.length} accounts* · yesterday's spend ${cur}${Math.round(total).toLocaleString('en-IN')}\n${lines.join('\n')}` } }];

// Pause result → confirmation text + alert-log update
const a = $('Parse Slack Button Payload').first().json;
const ok = $json.success === true;
const now = DateTime.now().setZone('Asia/Kolkata').toISO();
return [{ json: { ...a, ok,
  text: ok ? `⏸ <@${a.user_id}> paused ad *${a.entity_name}* (${a.client}).` : `❌ Could not pause *${a.entity_name}*: ${$json.error?.message || 'unknown error'} — check the token has ads_management.`,
  alert_updates: ok ? a.fingerprints.map(fp => ({ fingerprint: fp, status: 'actioned', last_action: 'paused ad', last_action_by: a.user_name, updated_at: now })) : [],
  log: { action: 'pause_ad', entity_id: a.ad_id, before: 'ACTIVE', after: ok ? 'PAUSED' : 'error' } } }];

// Guard-railed budget change (supports ad-set daily budgets; CBO campaigns are refused)
const a = $('Parse Slack Button Payload').first().json;
const as = $json;
const pct = Math.max(-a.max_budget_change_pct, Math.min(a.max_budget_change_pct, a.budget_pct));
const cur = Number(as.daily_budget) || 0;
if (as.error || !cur) {
  return [{ json: { ...a, valid: false, reason: as.error ? (as.error.message || 'API error') : 'Ad set has no daily budget (campaign budget / lifetime budget) — change it in Ads Manager.' } }];
}
const next = Math.max(100, Math.round(cur * (1 + pct / 100)));
return [{ json: { ...a, valid: true, pct, current_minor: cur, new_minor: next, adset_name: as.name || a.entity_name } }];

// Budget result → confirmation text + alert-log update
const c = $('Compute New Budget').first().json;
const now = DateTime.now().setZone('Asia/Kolkata').toISO();
const sym = $('Set Workflow Config').first().json.currency_symbol;
const fmt = m => sym + Math.round(m / 100).toLocaleString('en-IN');
const ok = c.valid && $json.success === true;
return [{ json: { ...c, ok,
  text: ok ? `${c.pct > 0 ? '📈' : '📉'} <@${c.user_id}> changed *${c.adset_name}* daily budget ${fmt(c.current_minor)} → *${fmt(c.new_minor)}* (${c.pct > 0 ? '+' : ''}${c.pct}%).`
           : `❌ Budget not changed for *${c.adset_name || c.entity_name}*: ${c.valid ? ($json.error?.message || 'API error') : c.reason}`,
  alert_updates: ok ? c.fingerprints.map(fp => ({ fingerprint: fp, status: 'actioned', last_action: `budget ${c.pct > 0 ? '+' : ''}${c.pct}%`, last_action_by: c.user_name, updated_at: now })) : [],
  log: { action: 'budget_change', entity_id: c.adset_id, before: c.valid ? String(c.current_minor) : '', after: ok ? String(c.new_minor) : 'error' } } }];

// Statistical anomaly detection (z-score vs 28-day baseline + same-weekday), pacing vs budget,
// creative fatigue (CTR trend + slope + frequency) and scale opportunities.
const acc = $('Get Current Account').first().json;
const n = v => Number(v) || 0;
const pages = name => { try { return $(name).all().map(i => i.json); } catch (e) { return []; } };
const rowsOf = name => pages(name).flatMap(p => p.data || []);
const errOf = name => pages(name).map(p => p.error).filter(Boolean).map(e => e.message || JSON.stringify(e))[0] || null;

const resultTypes = String(acc.result_action_types).split(',').map(s => s.trim()).filter(Boolean);
const valueTypes = String(acc.value_action_types).split(',').map(s => s.trim()).filter(Boolean);
const sumActs = (arr, types) => (arr || []).filter(a => types.includes(a.action_type)).reduce((s, a) => s + n(a.value), 0);
const mean = a => (a.length ? a.reduce((s, x) => s + x, 0) / a.length : 0);
const std = a => { if (a.length < 2) return 0; const m = mean(a); return Math.sqrt(a.reduce((s, x) => s + (x - m) ** 2, 0) / (a.length - 1)); };
const z = (x, a) => { const s = std(a); return s > 0 ? +((x - mean(a)) / s).toFixed(2) : null; };
const pct = (x, b) => (b > 0 ? +(((x - b) / b) * 100).toFixed(1) : null);
const slope = ys => { // least-squares slope, normalised to % of mean per day
  const k = ys.length; if (k < 3) return null;
  const xs = ys.map((_, i) => i), mx = mean(xs), my = mean(ys);
  const den = xs.reduce((s, x) => s + (x - mx) ** 2, 0); if (!den || !my) return null;
  return +((xs.reduce((s, x, i) => s + (x - mx) * (ys[i] - my), 0) / den) / my * 100).toFixed(2);
};
const money = v => acc.currency_symbol + Math.round(v).toLocaleString('en-IN');
const fmt = v => (v === null || v === undefined ? 'n/a' : (v > 0 ? '+' : '') + Math.round(v) + '%');
const ZT = n(acc.z_threshold), MIN = n(acc.min_daily_spend);
const issues = [];
const add = (type, severity, detail, metric = {}, entity = {}) => issues.push({
  type, severity, detail, metric,
  entity_type: entity.type || 'account', entity_id: entity.id || acc.account_id, entity_name: entity.name || acc.client_name,
  adset_id: entity.adset_id || null, adset_name: entity.adset_name || null
});

const apiErr = errOf('Fetch Account Daily') || errOf('Fetch Ad Daily') || errOf('Fetch Ad 7-Day Totals') || errOf('Fetch Active Ad Sets');
if (apiErr) add('API_ERROR', 'critical', `Meta API error: ${String(apiErr).slice(0, 220)}`);

// ---------- Account level ----------
const daily = rowsOf('Fetch Account Daily').map(r => ({
  date: r.date_start, spend: n(r.spend), imp: n(r.impressions), clk: n(r.clicks),
  res: sumActs(r.actions, resultTypes), val: sumActs(r.action_values, valueTypes)
})).sort((a, b) => a.date.localeCompare(b.date));

let summary = null;
if (daily.length >= 8) {
  const y = daily[daily.length - 1], base = daily.slice(0, -1);
  const dow = d => new Date(d + 'T00:00:00Z').getUTCDay();
  const sameDow = base.filter(r => dow(r.date) === dow(y.date));
  const series = {
    spend: base.map(r => r.spend),
    ctr: base.filter(r => r.imp).map(r => r.clk / r.imp * 100),
    cpm: base.filter(r => r.imp).map(r => r.spend / r.imp * 1000),
    cpa: base.filter(r => r.res).map(r => r.spend / r.res),
    roas: base.filter(r => r.spend && r.val).map(r => r.val / r.spend)
  };
  const yv = {
    spend: y.spend, ctr: y.imp ? y.clk / y.imp * 100 : 0, cpm: y.imp ? y.spend / y.imp * 1000 : 0,
    cpa: y.res ? y.spend / y.res : null, roas: y.spend && y.val ? y.val / y.spend : (y.spend ? 0 : null)
  };
  const stat = k => ({ value: yv[k] === null ? null : +yv[k].toFixed(2), baseline: +mean(series[k]).toFixed(2), pct: yv[k] === null ? null : pct(yv[k], mean(series[k])), z: yv[k] === null ? null : z(yv[k], series[k]) });
  summary = {
    date: y.date, baseline_days: base.length, results: y.res, results_avg: +mean(base.map(r => r.res)).toFixed(1),
    revenue: Math.round(y.val), spend: stat('spend'), ctr: stat('ctr'), cpm: stat('cpm'), cpa: stat('cpa'), roas: stat('roas'),
    same_weekday_spend_avg: Math.round(mean(sameDow.map(r => r.spend)))
  };
  const s = summary;
  if (y.spend === 0 && s.spend.baseline >= MIN) add('SPEND_STOPPED', 'critical', `No spend yesterday (28d avg ${money(s.spend.baseline)}). Check billing, disapprovals, paused campaigns.`, s.spend);
  else if (s.spend.z !== null && s.spend.z >= ZT && s.spend.pct >= n(acc.spend_spike_pct) && y.spend >= MIN)
    add('SPEND_SPIKE', s.spend.z >= ZT + 1 ? 'critical' : 'warning', `Spend ${money(y.spend)} is ${fmt(s.spend.pct)} vs 28d avg (z=${s.spend.z}; same-weekday avg ${money(s.same_weekday_spend_avg)}).`, s.spend);
  else if (s.spend.z !== null && s.spend.z <= -ZT && s.spend.pct <= -n(acc.spend_drop_pct) && s.spend.baseline >= MIN)
    add('SPEND_DROP', 'warning', `Spend ${money(y.spend)} is ${fmt(s.spend.pct)} vs 28d avg (z=${s.spend.z}) — delivery, learning or budget issue.`, s.spend);

  const baseCpa = s.cpa.baseline;
  if (y.res === 0 && y.spend >= Math.max(MIN, 2 * baseCpa) && s.results_avg >= 1)
    add('NO_RESULTS', 'critical', `${money(y.spend)} spent with 0 results (avg ${s.results_avg}/day). Check pixel/CAPI events and landing page.`, s.cpa);
  else if (s.cpa.z !== null && series.cpa.length >= 7 && s.cpa.z >= ZT && s.cpa.pct >= n(acc.cpa_spike_pct))
    add('CPA_SPIKE', s.cpa.z >= ZT + 1 ? 'critical' : 'warning', `CPA ${money(yv.cpa)} is ${fmt(s.cpa.pct)} vs 28d avg ${money(baseCpa)} (z=${s.cpa.z}).`, s.cpa);
  if (acc.target_cpa && yv.cpa && yv.cpa > n(acc.target_cpa) * 1.2)
    add('ABOVE_TARGET_CPA', 'warning', `CPA ${money(yv.cpa)} is ${fmt(pct(yv.cpa, n(acc.target_cpa)))} above target ${money(n(acc.target_cpa))}.`, { value: Math.round(yv.cpa), target: n(acc.target_cpa) });
  if (s.roas.z !== null && series.roas.length >= 7 && s.roas.z <= -ZT && s.roas.pct <= -n(acc.roas_drop_pct))
    add('ROAS_DROP', 'warning', `ROAS ${yv.roas.toFixed(2)}x is ${fmt(s.roas.pct)} vs 28d avg ${s.roas.baseline}x (z=${s.roas.z}).`, s.roas);
  if (s.ctr.z !== null && s.ctr.z <= -ZT && s.ctr.pct <= -n(acc.ctr_drop_pct))
    add('CTR_DROP', 'warning', `Account CTR ${yv.ctr.toFixed(2)}% is ${fmt(s.ctr.pct)} vs 28d avg ${s.ctr.baseline}% (z=${s.ctr.z}).`, s.ctr);
  if (s.cpm.z !== null && s.cpm.z >= ZT && s.cpm.pct >= n(acc.cpm_spike_pct))
    add('CPM_SPIKE', 'info', `CPM ${money(yv.cpm)} is ${fmt(s.cpm.pct)} vs 28d avg (z=${s.cpm.z}) — auction pressure or narrow audience.`, s.cpm);
} else if (!apiErr) {
  add('NO_DATA', 'warning', `Only ${daily.length} days of data returned — need 8+ for a statistical baseline.`);
}

// ---------- Budget pacing ----------
const adsets = rowsOf('Fetch Active Ad Sets');
const budgetSum = adsets.reduce((s, a) => s + n(a.daily_budget) / 100, 0); // Meta returns minor units
if (summary && budgetSum > 0 && summary.spend.value !== null) {
  const ratio = summary.spend.value / budgetSum;
  summary.pacing = { daily_budget_total: Math.round(budgetSum), ratio: +ratio.toFixed(2) };
  if (ratio < n(acc.underpace_ratio) && budgetSum >= MIN)
    add('UNDERPACING', 'warning', `Spent only ${Math.round(ratio * 100)}% of ${money(budgetSum)} active ad-set daily budgets — check bids/cost caps, audience size, learning limited.`, summary.pacing);
  else if (ratio > 1.25)
    add('OVERPACING', 'info', `Spend is ${Math.round(ratio * 100)}% of active ad-set daily budgets (${money(budgetSum)}).`, summary.pacing);
}

// ---------- Ad level ----------
const totals = Object.fromEntries(rowsOf('Fetch Ad 7-Day Totals').map(r => [r.ad_id, r]));
const byAd = {};
for (const r of rowsOf('Fetch Ad Daily')) {
  const a = (byAd[r.ad_id] ||= { ad_id: r.ad_id, ad_name: r.ad_name, adset_id: r.adset_id, adset_name: r.adset_name, campaign_name: r.campaign_name, rows: [] });
  a.rows.push({ date: r.date_start, spend: n(r.spend), imp: n(r.impressions), clk: n(r.clicks), res: sumActs(r.actions, resultTypes) });
}
const lastDate = summary?.date || Object.values(byAd).flatMap(a => a.rows.map(r => r.date)).sort().pop();
const agg = arr => arr.reduce((s, r) => ({ imp: s.imp + r.imp, clk: s.clk + r.clk, spend: s.spend + r.spend, res: s.res + r.res }), { imp: 0, clk: 0, spend: 0, res: 0 });
const fThr = n(acc.frequency_threshold), cThr = n(acc.ctr_drop_pct);
const fatigued = [], scale = {}, adsetYesterday = {};

for (const ad of Object.values(byAd)) {
  for (const r of ad.rows.filter(r => r.date === lastDate)) {
    const s = (adsetYesterday[ad.adset_id] ||= { adset_id: ad.adset_id, adset_name: ad.adset_name, spend: 0 }); s.spend += r.spend;
  }
  const active = ad.rows.filter(r => r.imp > 0).sort((a, b) => a.date.localeCompare(b.date));
  if (active.length < 5) continue;
  const total = agg(active);
  if (total.spend < n(acc.min_ad_spend_window)) continue;
  const recent = active.slice(-3), early = active.slice(0, Math.max(2, active.length - 3));
  const e = agg(early), r = agg(recent);
  const eCtr = e.imp ? e.clk / e.imp * 100 : 0, rCtr = r.imp ? r.clk / r.imp * 100 : 0;
  const eCpm = e.imp ? e.spend / e.imp * 1000 : 0, rCpm = r.imp ? r.spend / r.imp * 1000 : 0;
  const ctrChange = pct(rCtr, eCtr), cpmChange = pct(rCpm, eCpm);
  const ctrSlope = slope(active.map(x => (x.imp ? x.clk / x.imp * 100 : 0)));
  const freq = n(totals[ad.ad_id]?.frequency);
  const last7 = agg(active.slice(-7));
  const cpa7 = last7.res ? last7.spend / last7.res : null;

  const fatigue = (freq >= fThr && ctrChange !== null && ctrChange <= -cThr)
    || (ctrChange !== null && ctrChange <= -2 * cThr)
    || (freq >= fThr * 1.5)
    || (ctrSlope !== null && ctrSlope <= -4 && freq >= fThr * 0.8);
  if (fatigue) {
    const signals = [];
    if (freq >= fThr) signals.push(`freq ${freq.toFixed(1)}`);
    if (ctrChange !== null && ctrChange <= -cThr) signals.push(`CTR ${fmt(ctrChange)}`);
    if (ctrSlope !== null && ctrSlope < 0) signals.push(`CTR trend ${ctrSlope}%/day`);
    if (cpmChange !== null && cpmChange >= 25) signals.push(`CPM ${fmt(cpmChange)}`);
    const score = Math.round(Math.min(100, (fThr ? freq / fThr * 30 : 0) + Math.max(0, -(ctrChange || 0)) * 0.6 + Math.max(0, -(ctrSlope || 0)) * 3 + Math.max(0, cpmChange || 0) * 0.2));
    fatigued.push({ ad_id: ad.ad_id, ad_name: ad.ad_name, adset_id: ad.adset_id, adset_name: ad.adset_name, campaign_name: ad.campaign_name,
      spend_window: Math.round(total.spend), frequency: +freq.toFixed(2), ctr_early: +eCtr.toFixed(2), ctr_recent: +rCtr.toFixed(2),
      ctr_change: ctrChange, ctr_slope: ctrSlope, cpm_change: cpmChange, cpa_7d: cpa7 ? Math.round(cpa7) : null, signals, fatigue_score: score });
  } else if (acc.target_cpa && cpa7 && last7.res >= n(acc.min_results_scale) && cpa7 <= n(acc.target_cpa) * n(acc.scale_cpa_ratio) && freq < fThr && (ctrChange === null || ctrChange > -cThr / 2)) {
    const sc = (scale[ad.adset_id] ||= { adset_id: ad.adset_id, adset_name: ad.adset_name, ads: [], cpa_7d: cpa7, results_7d: 0 });
    sc.ads.push(ad.ad_name); sc.results_7d += last7.res; sc.cpa_7d = Math.min(sc.cpa_7d, cpa7);
  }
}
fatigued.sort((a, b) => b.fatigue_score - a.fatigue_score);
const topFatigued = fatigued.slice(0, n(acc.max_fatigued_ads) || 8);
for (const f of topFatigued) {
  add('CREATIVE_FATIGUE', f.fatigue_score >= 70 ? 'warning' : 'info', `${f.ad_name}: ${f.signals.join(', ')} (score ${f.fatigue_score}/100)`,
    { fatigue_score: f.fatigue_score, frequency: f.frequency, ctr_change: f.ctr_change }, { type: 'ad', id: f.ad_id, name: f.ad_name, adset_id: f.adset_id, adset_name: f.adset_name });
}
const scaleList = Object.values(scale).map(s => ({ ...s, cpa_7d: Math.round(s.cpa_7d), budget: n(adsets.find(a => a.id === s.adset_id)?.daily_budget) / 100 || null }));
for (const s of scaleList) {
  add('SCALE_OPPORTUNITY', 'info', `${s.adset_name}: 7d CPA ${money(s.cpa_7d)} vs target ${money(n(acc.target_cpa))} on ${Math.round(s.results_7d)} results — room to scale.`,
    { cpa_7d: s.cpa_7d, results_7d: s.results_7d }, { type: 'adset', id: s.adset_id, name: s.adset_name, adset_id: s.adset_id, adset_name: s.adset_name });
}
const topAdset = Object.values(adsetYesterday).sort((a, b) => b.spend - a.spend)[0] || null;
if (topAdset) {
  const as = adsets.find(a => a.id === topAdset.adset_id);
  topAdset.daily_budget = as ? n(as.daily_budget) / 100 : null;
  for (const i of issues.filter(i => ['SPEND_SPIKE', 'CPA_SPIKE', 'OVERPACING'].includes(i.type))) { i.adset_id = topAdset.adset_id; i.adset_name = topAdset.adset_name; }
}

return [{ json: {
  ...acc, summary, issues, fatigued_ads: topFatigued, scale_candidates: scaleList, top_adset_yesterday: topAdset,
  data_quality: { account_days: daily.length, ads_analyzed: Object.keys(byAd).length, adsets_active: adsets.length,
    ad_daily_pages: pages('Fetch Ad Daily').length }
}}];

// Alert memory: suppress snoozed issues, count consecutive days, escalate persistent ones, detect recoveries.
const d = $input.first().json;
const n = v => Number(v) || 0;
const tz = 'Asia/Kolkata';
const today = DateTime.now().setZone(tz).toISODate();
const yesterday = DateTime.now().setZone(tz).minus({ days: 1 }).toISODate();
const log = {};
for (const i of $('Read Alert Log Sheet').all()) if (i.json.fingerprint) log[i.json.fingerprint] = i.json;
const ESC = n(d.escalate_after_days) || 3;
const bump = { info: 'warning', warning: 'critical', critical: 'critical' };
const rank = { critical: 3, warning: 2, info: 1 };

const active = [], suppressed = [], upserts = [];
const seen = new Set();
for (const iss of d.issues) {
  const fp = `${d.account_id}|${iss.type}|${iss.entity_id}`;
  seen.add(fp);
  const row = log[fp];
  const wasOpen = row && ['open', 'snoozed', 'actioned'].includes(row.status);
  let consecutive = 1;
  if (row && wasOpen && row.last_seen === yesterday) consecutive = n(row.consecutive_days) + 1;
  else if (row && wasOpen && row.last_seen === today) consecutive = n(row.consecutive_days) || 1; // re-run same day
  const snoozed = row && row.status === 'snoozed' && String(row.snoozed_until || '') >= today;
  const escalated = consecutive >= ESC && iss.severity !== 'critical' && iss.type !== 'SCALE_OPPORTUNITY';
  const enriched = { ...iss, fingerprint: fp, consecutive_days: consecutive, is_new: consecutive === 1,
    escalated, severity: escalated ? bump[iss.severity] : iss.severity, first_seen: consecutive > 1 && row?.first_seen ? row.first_seen : today };
  (snoozed ? suppressed : active).push(enriched);
  upserts.push({
    fingerprint: fp, account_id: d.account_id, client: d.client_name, issue_type: iss.type, entity_type: iss.entity_type,
    entity_id: iss.entity_id, entity_name: String(iss.entity_name || '').slice(0, 120), severity: enriched.severity,
    detail: String(iss.detail).slice(0, 300), first_seen: enriched.first_seen, last_seen: today, consecutive_days: consecutive,
    status: snoozed ? 'snoozed' : 'open', snoozed_until: snoozed ? row.snoozed_until : '', updated_at: DateTime.now().setZone(tz).toISO()
  });
}
// Recovered: open alerts for this account not detected today
const recovered = [];
for (const [fp, row] of Object.entries(log)) {
  if (row.account_id !== d.account_id || seen.has(fp)) continue;
  if (!['open', 'actioned'].includes(row.status)) continue;
  recovered.push({ type: row.issue_type, entity_name: row.entity_name, days: n(row.consecutive_days) });
  upserts.push({ ...row, status: 'auto_resolved', updated_at: DateTime.now().setZone(tz).toISO() });
}
active.sort((a, b) => (rank[b.severity] || 0) - (rank[a.severity] || 0));
const severity = active.reduce((s, i) => (rank[i.severity] > (rank[s] || 0) ? i.severity : s), 'ok');
const alertable = active.some(i => i.type !== 'SCALE_OPPORTUNITY') || active.length > 0;
const activeFatigueIds = new Set(active.filter(i => i.type === 'CREATIVE_FATIGUE').map(i => i.entity_id));

return [{ json: {
  ...d, active_issues: active, suppressed_issues: suppressed, recovered, log_upserts: upserts,
  fatigued_ads: d.fatigued_ads.filter(f => activeFatigueIds.has(f.ad_id)),
  has_alertable: alertable, severity, run_date: today,
  thumbnail_ids: d.fatigued_ads.filter(f => activeFatigueIds.has(f.ad_id)).slice(0, 3).map(f => f.ad_id).join(',')
}}];

