// Build an interactive Slack Block Kit alert (buttons → Slack Action webhook in this same workflow)
const d = $('Dedupe & Escalate Alerts').first().json;
const ai = $json.output || {};
let thumbs = {};
try { const t = $('Fetch Creative Thumbnails').first().json; if (t && !t.error) thumbs = t; } catch (e) {}
const cur = d.currency_symbol, s = d.summary;
const money = v => (v === null || v === undefined ? 'n/a' : cur + Math.round(v).toLocaleString('en-IN'));
const dl = st => (!st || st.pct === null || st.pct === undefined ? '' : ` (${st.pct > 0 ? '+' : ''}${Math.round(st.pct)}%${st.z !== null ? `, z ${st.z}` : ''})`);
const sevEmoji = { critical: '🔴', warning: '🟠', info: '🔵' };
const head = { critical: '🚨', warning: '⚠️', info: '🔵' }[d.severity] || '📊';
const actNum = String(d.account_id).replace('act_', '');
const trunc = (t, m) => (String(t).length > m ? String(t).slice(0, m - 1) + '…' : String(t));
const val = o => JSON.stringify({ ...o, acc: d.account_id, c: trunc(d.client_name, 40) }).slice(0, 1900);
const B = [];

B.push({ type: 'header', text: { type: 'plain_text', text: trunc(`${head} Meta Ads — ${d.client_name}`, 150), emoji: true } });
B.push({ type: 'context', elements: [{ type: 'mrkdwn', text: `*${s?.date || d.until}* · ${d.account_id} · severity *${d.severity.toUpperCase()}* · ${d.active_issues.length} active · ${d.suppressed_issues.length} snoozed · baseline ${s?.baseline_days || 0}d` }] });
if (ai.headline) B.push({ type: 'section', text: { type: 'mrkdwn', text: trunc(`*${ai.headline}*${ai.root_cause ? `\n_Likely root cause (${ai.confidence || 'medium'} confidence):_ ${ai.root_cause}` : ''}`, 2900) } });
if (s) B.push({ type: 'section', fields: [
  { type: 'mrkdwn', text: `*Spend*\n${money(s.spend.value)}${dl(s.spend)}` },
  { type: 'mrkdwn', text: `*CPA*\n${money(s.cpa.value)}${dl(s.cpa)}${d.target_cpa ? ` · target ${money(d.target_cpa)}` : ''}` },
  { type: 'mrkdwn', text: `*ROAS*\n${s.roas.value === null ? 'n/a' : s.roas.value + 'x'}${dl(s.roas)}` },
  { type: 'mrkdwn', text: `*CTR*\n${s.ctr.value}%${dl(s.ctr)}` },
  { type: 'mrkdwn', text: `*CPM*\n${money(s.cpm.value)}${dl(s.cpm)}` },
  { type: 'mrkdwn', text: `*Pacing*\n${s.pacing ? `${Math.round(s.pacing.ratio * 100)}% of ${money(s.pacing.daily_budget_total)}` : 'n/a (CBO / no ad-set budgets)'}` }
] });
B.push({ type: 'divider' });

const acctIssues = d.active_issues.filter(i => i.type !== 'CREATIVE_FATIGUE' && i.type !== 'SCALE_OPPORTUNITY');
if (acctIssues.length) {
  B.push({ type: 'section', text: { type: 'mrkdwn', text: trunc('*Account anomalies*\n' + acctIssues.map(i =>
    `${sevEmoji[i.severity] || '•'} *${i.type.replace(/_/g, ' ')}* ${i.is_new ? '🆕' : `🔁 day ${i.consecutive_days}`}${i.escalated ? ' ⬆️ escalated' : ''}\n${i.detail}`).join('\n'), 2900) } });
  const spike = acctIssues.find(i => ['SPEND_SPIKE', 'CPA_SPIKE'].includes(i.type) && i.adset_id);
  const els = [];
  if (spike && d.top_adset_yesterday?.daily_budget) els.push({ type: 'button', style: 'danger', action_id: 'budget_down',
    text: { type: 'plain_text', text: `📉 Cut "${trunc(spike.adset_name, 30)}" −${d.budget_step_pct}%` },
    value: val({ a: 'budget', adset: spike.adset_id, n: trunc(spike.adset_name, 60), p: -n(d.budget_step_pct), fp: spike.fingerprint }),
    confirm: { title: { type: 'plain_text', text: 'Reduce budget?' }, text: { type: 'mrkdwn', text: `Lower daily budget of *${trunc(spike.adset_name, 80)}* by ${d.budget_step_pct}% (now ${money(d.top_adset_yesterday.daily_budget)}).` }, confirm: { type: 'plain_text', text: 'Reduce' }, deny: { type: 'plain_text', text: 'Cancel' } } });
  els.push({ type: 'button', action_id: 'snooze_account', text: { type: 'plain_text', text: `😴 Snooze anomalies ${d.snooze_days}d` },
    value: val({ a: 'snooze', fps: acctIssues.map(i => i.fingerprint) }) });
  els.push({ type: 'button', action_id: 'resolve_account', text: { type: 'plain_text', text: '✅ Mark handled' },
    value: val({ a: 'resolve', fps: acctIssues.map(i => i.fingerprint) }) });
  B.push({ type: 'actions', block_id: 'acct_actions', elements: els });
}

const fat = d.fatigued_ads.slice(0, 4);
if (fat.length) {
  B.push({ type: 'divider' });
  B.push({ type: 'section', text: { type: 'mrkdwn', text: `*🎨 Creative fatigue* — ${fat.length} of ${d.data_quality.ads_analyzed} active ads` } });
  fat.forEach((f, idx) => {
    const iss = d.active_issues.find(i => i.type === 'CREATIVE_FATIGUE' && i.entity_id === f.ad_id);
    const thumb = thumbs[f.ad_id]?.creative?.thumbnail_url;
    const sec = { type: 'section', text: { type: 'mrkdwn', text: trunc(`*${f.ad_name}* ${iss?.is_new ? '🆕' : `🔁 day ${iss?.consecutive_days}`}\n${f.adset_name}\nScore *${f.fatigue_score}/100* · ${f.signals.join(' · ')}\nCTR ${f.ctr_early}% → ${f.ctr_recent}% · ${money(f.spend_window)} spent · 7d CPA ${money(f.cpa_7d)}`, 2900) } };
    if (thumb) sec.accessory = { type: 'image', image_url: thumb, alt_text: trunc(f.ad_name, 100) };
    B.push(sec);
    B.push({ type: 'actions', block_id: `fat_${idx}`, elements: [
      { type: 'button', style: 'danger', action_id: `pause_${idx}`, text: { type: 'plain_text', text: '⏸ Pause ad' },
        value: val({ a: 'pause', ad: f.ad_id, n: trunc(f.ad_name, 60), fp: iss?.fingerprint }),
        confirm: { title: { type: 'plain_text', text: 'Pause this ad?' }, text: { type: 'mrkdwn', text: `*${trunc(f.ad_name, 120)}* will stop delivering immediately.` }, confirm: { type: 'plain_text', text: 'Pause' }, deny: { type: 'plain_text', text: 'Cancel' } } },
      { type: 'button', action_id: `snooze_ad_${idx}`, text: { type: 'plain_text', text: `😴 Snooze ${d.snooze_days}d` }, value: val({ a: 'snooze', fps: [iss?.fingerprint].filter(Boolean) }) }
    ] });
  });
}

const sc = d.active_issues.filter(i => i.type === 'SCALE_OPPORTUNITY').slice(0, 3);
if (sc.length) {
  B.push({ type: 'divider' });
  B.push({ type: 'section', text: { type: 'mrkdwn', text: trunc('*📈 Scale opportunities*\n' + sc.map(i => `• ${i.detail}`).join('\n'), 2900) } });
  B.push({ type: 'actions', block_id: 'scale_actions', elements: sc.map((i, idx) => ({ type: 'button', style: 'primary', action_id: `scale_${idx}`,
    text: { type: 'plain_text', text: trunc(`📈 +${d.budget_step_pct}% ${i.entity_name}`, 70) },
    value: val({ a: 'budget', adset: i.entity_id, n: trunc(i.entity_name, 60), p: n(d.budget_step_pct), fp: i.fingerprint }),
    confirm: { title: { type: 'plain_text', text: 'Increase budget?' }, text: { type: 'mrkdwn', text: `Raise daily budget of *${trunc(i.entity_name, 80)}* by ${d.budget_step_pct}%.` }, confirm: { type: 'plain_text', text: 'Increase' }, deny: { type: 'plain_text', text: 'Cancel' } } })) });
}

if (Array.isArray(ai.fixes) && ai.fixes.length) {
  B.push({ type: 'divider' });
  B.push({ type: 'section', text: { type: 'mrkdwn', text: trunc('*💡 AI action plan*\n' + ai.fixes.slice(0, 5).map((f, i) =>
    `${i + 1}. \`${String(f.priority || 'medium').toUpperCase()}\` *${f.issue}* → ${f.action}${f.expected_impact ? ` _(${f.expected_impact})_` : ''}`).join('\n'), 2900) } });
}
if (Array.isArray(ai.creative_ideas) && ai.creative_ideas.length)
  B.push({ type: 'section', text: { type: 'mrkdwn', text: trunc('*🎬 Fresh creative angles*\n' + ai.creative_ideas.slice(0, 3).map(c => `• ${c}`).join('\n'), 2900) } });
if (d.recovered.length)
  B.push({ type: 'context', elements: [{ type: 'mrkdwn', text: trunc('✅ Recovered since last run: ' + d.recovered.map(r => `${r.type.replace(/_/g, ' ').toLowerCase()} (${r.entity_name})`).join(', '), 2900) }] });
B.push({ type: 'actions', block_id: 'links', elements: [{ type: 'button', action_id: 'open_ads_manager', text: { type: 'plain_text', text: 'Open Ads Manager' },
  url: `https://adsmanager.facebook.com/adsmanager/manage/ads?act=${actNum}` }] });
if (ai.watch_next) B.push({ type: 'context', elements: [{ type: 'mrkdwn', text: trunc(`👀 *Watch next:* ${ai.watch_next}`, 2900) }] });

function n(v) { return Number(v) || 0; }
return [{ json: { slack_channel: d.slack_channel, blocks: B.slice(0, 50),
  fallback_text: `${head} Meta Ads — ${d.client_name}: ${d.active_issues.length} issue(s), severity ${d.severity}` } }];

// Collect alert-log rows for this account (always outputs one item so the loop keeps running)
const d = $('Dedupe & Escalate Alerts').first().json;
return [{ json: { rows: d.log_upserts, count: d.log_upserts.length } }];

// One summary item per account → fed back into the loop
const d = $('Dedupe & Escalate Alerts').first().json;
return [{ json: {
  client: d.client_name, account_id: d.account_id, severity: d.severity,
  active: d.active_issues.length, suppressed: d.suppressed_issues.length, recovered: d.recovered.length,
  critical: d.active_issues.filter(i => i.severity === 'critical').length,
  fatigued: d.fatigued_ads.length, scale: d.active_issues.filter(i => i.type === 'SCALE_OPPORTUNITY').length,
  spend: d.summary?.spend?.value ?? null, alerted: d.has_alertable
}}];
